"""Object storage for generated reports and support screenshots (doc 03 section 5, doc 07 T21).

* Keys are generated by the server only (``<prefix>/<uuid>.<ext>``) and checked against the same
  pattern as the database domain ``common.object_key``; no user-supplied name ever reaches a path.
* ``FilesystemStorage`` (dev, and any host without an object store): one folder per container under
  ``STORAGE_ROOT_DIR`` (key prefix ``reports`` -> ``STORAGE_CONTAINER_REPORTS``, ``support`` ->
  ``STORAGE_CONTAINER_ATTACHMENTS``). Files are served back only through authenticated API routes
  that check the owner first, so there is no public URL to leak. A cloud store with short-lived
  signed URLs can replace it later behind the same interface (the app treats the download URL as
  opaque).
* Writes go to a temporary file and are renamed into place, so a reader never sees half a file.
"""

from __future__ import annotations

import os
import uuid
from pathlib import Path
from typing import Protocol

import anyio.to_thread
import regex

from app.core.config import Settings

KEY_PATTERN = regex.compile(r"^[a-z]+/[0-9a-f-]{36}(/[a-z0-9_-]{1,40})?\.(png|jpg|pdf|zip)$")


def new_key(prefix: str, extension: str) -> str:
    key = f"{prefix}/{uuid.uuid4()}.{extension}"
    if not KEY_PATTERN.match(key):
        raise ValueError("invalid object key")
    return key


class ObjectStorage(Protocol):
    async def put(self, key: str, data: bytes) -> None: ...
    async def get(self, key: str) -> bytes | None: ...
    async def delete(self, key: str) -> None: ...


class FilesystemStorage:
    def __init__(self, root: Path, containers: dict[str, str]) -> None:
        self._root = root.resolve()
        self._containers = dict(containers)

    def _path(self, key: str) -> Path:
        if not KEY_PATTERN.match(key):
            raise ValueError("invalid object key")
        prefix, rest = key.split("/", 1)
        container = self._containers.get(prefix)
        if container is None:
            raise ValueError("unknown storage container")
        path = (self._root / container / rest).resolve()
        if self._root not in path.parents:
            raise ValueError("invalid object key")
        return path

    def _put_sync(self, path: Path, data: bytes) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
        tmp.write_bytes(data)
        os.replace(tmp, path)

    async def put(self, key: str, data: bytes) -> None:
        await anyio.to_thread.run_sync(self._put_sync, self._path(key), data)

    async def get(self, key: str) -> bytes | None:
        path = self._path(key)
        try:
            return await anyio.to_thread.run_sync(path.read_bytes)
        except FileNotFoundError:
            return None

    async def delete(self, key: str) -> None:
        path = self._path(key)
        await anyio.to_thread.run_sync(lambda: path.unlink(missing_ok=True))


def build_storage(settings: Settings) -> ObjectStorage:
    """Reports and support screenshots (S14). Filesystem only for now (no AWS, doc 03)."""
    return FilesystemStorage(
        Path(settings.STORAGE_ROOT_DIR),
        {
            "reports": settings.STORAGE_CONTAINER_REPORTS,
            "support": settings.STORAGE_CONTAINER_ATTACHMENTS,
        },
    )
